INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Счет Трейд Ресурс 12.10 МБТ в загрузку OData', 'Счёт ООО «ВГ-ТРЕЙД» (Weissgauff) № 1178 от 12.10.2026 по правилу «Создание файла для OData». Восемь колонок: Артикул (колонка «Код», текстом), Штрихкод (из счёта, текстом), Наименование (как в счёте), Количество, Цена с НДС, Страна, Номер ГТД, Номер РНПТ (в счёте нет — пусто). Порядок строк как в счёте, повторы не схлопнуты (пылесос V11 и швабра WSM-10 — по две строки). 204 строки, 1 125 шт, 2 343 890,00 руб. — сходится с итогом счёта до копейки.', '/converted/schet-treid-resurs-12-10-mbt-v-zagruzku-odata.xlsx', 'Счет Трейд Ресурс 12.10 МБТ в загрузку OData.xlsx', 'converted/schet-treid-resurs-12-10-mbt-v-zagruzku-odata.xlsx', 16595);